/// Unicode `BidiClass` property.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(u16)]
pub enum BidiClass {
    /// UCD value `AL`.
    Al,
    /// UCD value `AN`.
    An,
    /// UCD value `B`.
    B,
    /// UCD value `BN`.
    Bn,
    /// UCD value `CS`.
    Cs,
    /// UCD value `EN`.
    En,
    /// UCD value `ES`.
    Es,
    /// UCD value `ET`.
    Et,
    /// UCD value `FSI`.
    Fsi,
    /// UCD value `L`.
    L,
    /// UCD value `LRE`.
    Lre,
    /// UCD value `LRI`.
    Lri,
    /// UCD value `LRO`.
    Lro,
    /// UCD value `NSM`.
    Nsm,
    /// UCD value `ON`.
    On,
    /// UCD value `PDF`.
    Pdf,
    /// UCD value `PDI`.
    Pdi,
    /// UCD value `R`.
    R,
    /// UCD value `RLE`.
    Rle,
    /// UCD value `RLI`.
    Rli,
    /// UCD value `RLO`.
    Rlo,
    /// UCD value `S`.
    S,
    /// UCD value `WS`.
    Ws,
}

/// Look up `BidiClass`; out-of-range input has the default value.
#[must_use]
pub fn bidi_class(code: u32) -> BidiClass {
    lookup(BIDI_CLASS, code, BidiClass::L)
}

